/**
 * ImportPage — Connect step.
 *
 * Supports two import sources:
 *   1. ZIP upload (existing safe ingestion pipeline)
 *   2. Public GitHub URL (new v1 adapter)
 *
 * Both sources feed the same v1 snapshot model.
 * The page shows real progress stages; no fake percentages.
 * Privacy policy copy matches actual behavior (no invented claims).
 */

import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { importGitHub, importZip } from '../services/v1/api'
import type { ImportAccepted, Snapshot } from '../types/v1'
import { listSnapshots } from '../services/v1/api'

type ImportTab = 'github' | 'zip'

interface RecentImport {
  projectId: string
  snapshotId: string
  name: string
  importedAt: string
  kind: 'github' | 'zip'
}

type Stage =
  | 'idle'
  | 'validating'
  | 'uploading'
  | 'extracting'
  | 'indexing'
  | 'done'
  | 'error'

const STAGE_LABELS: Record<Stage, string> = {
  idle: '',
  validating: 'Validating…',
  uploading: 'Uploading archive…',
  extracting: 'Extracting and inventorying files…',
  indexing: 'Building structural index…',
  done: 'Ready',
  error: 'Import failed',
}

const RECENT_KEY = 'grepo:recent_imports'

function loadRecent(): RecentImport[] {
  try {
    return JSON.parse(localStorage.getItem(RECENT_KEY) ?? '[]') as RecentImport[]
  } catch {
    return []
  }
}

function saveRecent(imports: RecentImport[]) {
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(imports.slice(0, 10)))
  } catch {
    // storage may be unavailable
  }
}

export function ImportPage() {
  const navigate = useNavigate()
  const [tab, setTab] = useState<ImportTab>('github')
  const [githubUrl, setGithubUrl] = useState('')
  const [githubRef, setGithubRef] = useState('')
  const [zipFile, setZipFile] = useState<File | null>(null)
  const [stage, setStage] = useState<Stage>('idle')
  const [error, setError] = useState<string | null>(null)
  const [recent, setRecent] = useState<RecentImport[]>(loadRecent)
  const abortRef = useRef<AbortController | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  async function handleGitHubImport() {
    setError(null)
    setStage('validating')

    try {
      setStage('uploading')
      const accepted: ImportAccepted = await importGitHub({
        url: githubUrl,
        ref: githubRef || 'HEAD',
      })

      setStage('indexing')
      const snaps = await listSnapshots(accepted.project_id)
      const snap = snaps[snaps.length - 1]

      if (snap) {
        addRecent({
          projectId: accepted.project_id,
          snapshotId: snap.id,
          name: githubUrl.replace('https://github.com/', ''),
          importedAt: new Date().toISOString(),
          kind: 'github',
        })
        setStage('done')
        navigate(`/p/${accepted.project_id}/s/${snap.id}/overview`)
      } else {
        setError('Import completed but no snapshot was created. Please retry.')
        setStage('error')
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'GitHub import failed.')
      setStage('error')
    }
  }

  async function handleZipImport() {
    if (!zipFile) return
    setError(null)
    setStage('validating')

    try {
      setStage('uploading')
      const accepted: ImportAccepted = await importZip(zipFile)

      setStage('indexing')
      const snaps = await listSnapshots(accepted.project_id)
      const snap = snaps[snaps.length - 1]

      if (snap) {
        addRecent({
          projectId: accepted.project_id,
          snapshotId: snap.id,
          name: zipFile.name.replace(/\.zip$/i, ''),
          importedAt: new Date().toISOString(),
          kind: 'zip',
        })
        setStage('done')
        navigate(`/p/${accepted.project_id}/s/${snap.id}/overview`)
      } else {
        setError('Import completed but no snapshot was created. Please retry.')
        setStage('error')
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'ZIP import failed.')
      setStage('error')
    }
  }

  function addRecent(item: RecentImport) {
    setRecent(prev => {
      const next = [item, ...prev.filter(r => r.projectId !== item.projectId)].slice(0, 10)
      saveRecent(next)
      return next
    })
  }

  const isLoading = stage !== 'idle' && stage !== 'done' && stage !== 'error'
  const canSubmitGitHub = githubUrl.trim().startsWith('https://github.com/') && !isLoading
  const canSubmitZip = zipFile !== null && !isLoading

  return (
    <div className="import-page" role="main">
      <div className="import-hero">
        <img
          src="/grepo-logo.png"
          alt="Grepo — gecko mascot"
          className="import-hero__logo"
        />
        <h1 className="import-hero__tagline">
          Understand the repository.<br />Find your path to change.
        </h1>
        <p className="import-hero__sub">
          Import a repository, explore its structure, and navigate to the code that matters for your change.
          No sign-in required for local analysis.
        </p>

        <ol className="import-steps" aria-label="Three-step journey">
          <li className="import-step">
            <div className="import-step__num" aria-hidden="true">1</div>
            <div className="import-step__label">Connect</div>
          </li>
          <li className="import-step">
            <div className="import-step__num" aria-hidden="true">2</div>
            <div className="import-step__label">Understand</div>
          </li>
          <li className="import-step">
            <div className="import-step__num" aria-hidden="true">3</div>
            <div className="import-step__label">Plan</div>
          </li>
        </ol>

        <div className="import-card">
          {/* Source tabs */}
          <div className="import-card__tabs" role="tablist" aria-label="Import source">
            <button
              type="button"
              role="tab"
              id="tab-github"
              aria-controls="panel-github"
              aria-selected={tab === 'github'}
              className={`import-tab ${tab === 'github' ? 'import-tab--active' : ''}`}
              onClick={() => setTab('github')}
            >
              GitHub URL
            </button>
            <button
              type="button"
              role="tab"
              id="tab-zip"
              aria-controls="panel-zip"
              aria-selected={tab === 'zip'}
              className={`import-tab ${tab === 'zip' ? 'import-tab--active' : ''}`}
              onClick={() => setTab('zip')}
            >
              Upload ZIP
            </button>
          </div>

          {/* GitHub panel */}
          {tab === 'github' && (
            <div
              role="tabpanel"
              id="panel-github"
              aria-labelledby="tab-github"
              className="import-form"
            >
              <div className="import-form__field">
                <label className="form-label" htmlFor="github-url">
                  Public GitHub repository URL
                </label>
                <input
                  id="github-url"
                  type="url"
                  className="form-input"
                  placeholder="https://github.com/owner/repository"
                  value={githubUrl}
                  onChange={e => setGithubUrl(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && canSubmitGitHub && handleGitHubImport()}
                  disabled={isLoading}
                  aria-describedby="github-url-hint"
                />
                <p id="github-url-hint" style={{ margin: '6px 0 0', fontSize: 11, color: 'var(--grepo-text-secondary)' }}>
                  Only public repositories are supported. The URL must start with https://github.com/
                </p>
              </div>
              <div className="import-form__field">
                <label className="form-label" htmlFor="github-ref">
                  Branch or tag (optional, defaults to main branch)
                </label>
                <input
                  id="github-ref"
                  type="text"
                  className="form-input"
                  placeholder="main"
                  value={githubRef}
                  onChange={e => setGithubRef(e.target.value)}
                  disabled={isLoading}
                />
              </div>
              <button
                type="button"
                className="btn btn--primary"
                onClick={handleGitHubImport}
                disabled={!canSubmitGitHub}
                aria-busy={isLoading}
              >
                {isLoading ? (
                  <>
                    <span className="spinner" aria-hidden="true" />
                    {STAGE_LABELS[stage]}
                  </>
                ) : 'Import repository'}
              </button>
            </div>
          )}

          {/* ZIP panel */}
          {tab === 'zip' && (
            <div
              role="tabpanel"
              id="panel-zip"
              aria-labelledby="tab-zip"
              className="import-form"
            >
              <div className="import-form__field">
                <label className="form-label" htmlFor="zip-file">
                  ZIP archive
                </label>
                <input
                  ref={fileInputRef}
                  id="zip-file"
                  type="file"
                  accept=".zip"
                  className="form-input"
                  onChange={e => setZipFile(e.target.files?.[0] ?? null)}
                  disabled={isLoading}
                  aria-describedby="zip-file-hint"
                />
                <p id="zip-file-hint" style={{ margin: '6px 0 0', fontSize: 11, color: 'var(--grepo-text-secondary)' }}>
                  Maximum 50 MiB compressed, 250 MiB extracted, 10,000 entries.
                </p>
              </div>
              <button
                type="button"
                className="btn btn--primary"
                onClick={handleZipImport}
                disabled={!canSubmitZip}
                aria-busy={isLoading}
              >
                {isLoading ? (
                  <>
                    <span className="spinner" aria-hidden="true" />
                    {STAGE_LABELS[stage]}
                  </>
                ) : 'Upload and import'}
              </button>
            </div>
          )}

          {/* Error */}
          {error && (
            <div className="alert alert--error" role="alert" style={{ marginTop: 16 }}>
              {error}
              <button
                type="button"
                style={{ marginLeft: 12, fontWeight: 600, cursor: 'pointer', border: 0, background: 'none', color: 'inherit' }}
                onClick={() => { setError(null); setStage('idle') }}
              >
                Dismiss
              </button>
            </div>
          )}

          {/* Policy notice */}
          <p className="import-policy-notice">
            Grepo analyzes this repository without modifying it.
            Selected code excerpts may be sent to your configured IBM Watson service if AI features are enabled.
            Static structural browsing works without AI credentials.
            <strong> Do not upload repositories that contain sensitive credentials or private data.</strong>
          </p>
        </div>

        {/* Recent imports */}
        {recent.length > 0 && (
          <div className="recent-list" aria-label="Recent imports">
            <p className="recent-list__heading">Recent</p>
            {recent.map(item => (
              <button
                key={item.projectId}
                type="button"
                className="recent-item"
                onClick={() => navigate(`/p/${item.projectId}/s/${item.snapshotId}/overview`)}
              >
                <span className="recent-item__name">
                  {item.kind === 'github' ? '⊞ ' : '📦 '}{item.name}
                </span>
                <span className="recent-item__meta">
                  {new Date(item.importedAt).toLocaleDateString()}
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
